const __pageData = JSON.parse('{"title":"Week 15 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-15.md","filePath":"solutions/week-15.md"}');
